clc;
close all;
clear;
c = 2;
b = 5;
s1 = [1 2 -3 4];
s2 = [2 -2 5 4 6];
l1 = length(s1);
l2 = length(s2);
if(l1< l2)
    s1 = [s1 zeros(1,l2-l1)];
else
    s2 = [s2 zeros(1,l1-l2)];
end
s11 = s1;
s21 = s2;
y1 = exp(s11);
y2 = exp(s21);

out1 = exp(b*s11 + c*s21);
out2 = b*y1 + c*y2;
tol = 0.0001;
if (sum(abs(out2-out1)) < tol) %[output:group:57b19b0f]
    disp("System Is Linear");
else
    disp("System Is Non Linear"); %[output:90c1b967]
end %[output:group:57b19b0f]
n_out1 = 0:length(out1)-1;
n_out2 = 0:length(out2)-1;
figure(1); %[output:5879ad3e]
stem(n_out1,out1); %[output:5879ad3e]
xlabel("Sample"); %[output:5879ad3e]
ylabel("Amplitude"); %[output:5879ad3e]
title("Linearity Test"); %[output:5879ad3e]
figure(2); %[output:2ef47ec5]
stem(n_out2,out2); %[output:2ef47ec5]
xlabel("Sample"); %[output:2ef47ec5]
ylabel("Amplitude"); %[output:2ef47ec5]
title("Linearity Test"); %[output:2ef47ec5]




